"""Generated bytes only; no real OCI source, network, Docker, or admission."""

import json
import os
import signal
import subprocess
import sys
import unittest
from pathlib import Path
from unittest import mock

sys.path.insert(0, str(Path(__file__).parent))
import e3_n1_finite_closure as closure


class FiniteClosureTests(unittest.TestCase):
    def run_probe(self, mode, seconds):
        process = subprocess.Popen([sys.executable, "-I", "-B", str(Path(closure.__file__)),
                                    "probe", mode, str(seconds)],
                                   stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                   stderr=subprocess.PIPE, close_fds=True)
        raw = process.stdout.read()
        errors = process.stderr.read()
        pid, status, usage = os.wait4(process.pid, 0)
        process.returncode = os.waitstatus_to_exitcode(status)
        process.stdout.close()
        process.stderr.close()
        self.assertEqual(pid, process.pid)
        self.assertEqual(process.returncode, 0, errors)
        self.assertEqual(errors, b"")
        self.assertGreater(usage.ru_maxrss, 0)
        record = json.loads(raw)
        self.assertEqual(record["schema"], closure.SCHEMA)
        self.assertEqual(record["status"], "HOLD")
        self.assertEqual(record["resource_proof"], "HOLD")
        return record, usage.ru_maxrss * 1024

    def test_detached_holder_is_adopted_reaped_and_pipe_closes(self):
        record, controller_peak = self.run_probe("normal", 1)
        if not record.get("network_filter_loaded"):
            self.skipTest("Linux subreaper/pidfd/seccomp prerequisite unavailable: " + record["reason"])
        self.assertEqual(record["reason"], "unconfined-process-set-and-no-custody")
        self.assertTrue(record["known_actors_reaped"])
        self.assertTrue(record["pipes_eof"])
        self.assertTrue(record["actor_network_denied"])
        self.assertEqual(set(record["actor_peaks"]), {"leader", "holder"})
        self.assertEqual(record["actor_exit_codes"], {"leader": 0, "holder": 0})
        self.assertTrue(all(value > 0 for value in record["actor_peaks"].values()))
        self.assertGreater(controller_peak, 0)
        self.assertLessEqual(record["elapsed_ns"], record["cap_ns"])
        self.assertEqual(record["rss_cap_bytes"], 268435456)

    def test_late_detached_holder_is_signaled_by_pidfd_then_reaped(self):
        record, _ = self.run_probe("late", 0.5)
        if not record.get("network_filter_loaded"):
            self.skipTest("Linux subreaper/pidfd/seccomp prerequisite unavailable: " + record["reason"])
        self.assertEqual(record["reason"], "deadline")
        if record.get("actor_exit_codes", {}).get("holder") == 7:
            self.skipTest("fixed actor reached deadline before holder ACK on this host")
        self.assertTrue(record["known_actors_reaped"])
        self.assertTrue(record["pipes_eof"])
        self.assertEqual(set(record["actor_peaks"]), {"leader", "holder"})
        self.assertEqual(record["actor_exit_codes"], {"leader": 0,
                                                      "holder": -signal.SIGKILL})
        self.assertTrue(record["actor_network_denied"])

    def test_missing_linux_prerequisite_does_not_launch(self):
        with (mock.patch.object(closure, "_isolate", side_effect=closure.Hold("unsupported")),
              mock.patch.object(closure.subprocess, "Popen") as popen):
            with self.assertRaisesRegex(closure.Hold, "unsupported"):
                closure._probe("normal", 1)
        popen.assert_not_called()

    def test_unreviewed_mode_or_relaxed_time_is_rejected(self):
        for mode, seconds in (("other", 1), ("normal", 31), ("normal", 0)):
            with self.subTest(mode=mode, seconds=seconds):
                with self.assertRaises(closure.Hold):
                    closure._probe(mode, seconds)


if __name__ == "__main__":
    unittest.main()
